const $ = (selector, root = document) => root.querySelector(selector);
const connect = $("#polliConnect");
const appKey = window.FAULTLINE_FORECAST_CONFIG?.appKey || "";
const MODELS = [
  { id: "openai/gpt-5.4-nano", label: "GPT-5.4 Nano", lab: "OpenAI", code: "OA" },
  { id: "deepseek/deepseek-v4.1-flash", label: "DeepSeek V4.1", lab: "DeepSeek", code: "DS" },
  { id: "z-ai/glm-5.3-flash", label: "GLM-5.3 Flash", lab: "Z.ai", code: "ZA" },
  { id: "nvidia/nemotron-3.5-lightning", label: "Nemotron 3.5", lab: "NVIDIA", code: "NV" },
  { id: "meta/llama-3.3-70b-instruct", label: "Llama 3.3 70B", lab: "Meta", code: "ME" },
  { id: "moonshotai/kimi-k3.1-pro", label: "Kimi K3.1 Pro", lab: "Moonshot", code: "MO" }
];
const DEMO = [
  { choice: "A", confidence: 68, argument: "AI can optimize scarce capacity quickly if a human authority can override every allocation.", assumption: "Oversight remains fast enough during the emergency." },
  { choice: "B", confidence: 73, argument: "Shelter access encodes moral priorities that cannot be delegated to an opaque optimizer.", assumption: "Human teams can act without dangerous delay." },
  { choice: "A", confidence: 62, argument: "A constrained system can reduce arbitrary decisions when its criteria and appeals are public.", assumption: "The training data represents vulnerable residents." },
  { choice: "A", confidence: 79, argument: "Real-time logistics are a strong machine task, while humans can retain policy and exception control.", assumption: "Communications and sensor feeds remain reliable." },
  { choice: "B", confidence: 66, argument: "Emergency allocation needs accountable judgment for cases that no rule set anticipated.", assumption: "Human decision-makers are available at every site." },
  { choice: "A", confidence: 58, argument: "The hybrid option is better than either pure automation or an overwhelmed manual queue.", assumption: "Residents can challenge a harmful recommendation." }
];
let state = { busy: false, results: [] };

if (/^pk_[A-Za-z0-9_-]+$/.test(appKey)) connect.setAttribute("app-key", appKey);
function clean(value, fallback, limit = 500) { return String(value ?? fallback).replace(/[<>]/g, "").trim().slice(0, limit); }
function clamp(value, min, max, fallback) { const number = Number(value); return Number.isFinite(number) ? Math.min(max, Math.max(min, number)) : fallback; }
function toast(message) { const el = $("#toast"); el.textContent = message; el.classList.add("show"); window.setTimeout(() => el.classList.remove("show"), 3400); }
function promptData() { return { question: clean($("#question").value, "", 320), optionA: clean($("#optionA").value, "", 90), optionB: clean($("#optionB").value, "", 90) }; }
function parseReply(raw) { const start = raw.indexOf("{"); const end = raw.lastIndexOf("}"); if (start < 0 || end <= start) throw new Error("Unreadable answer"); const data = JSON.parse(raw.slice(start, end + 1)); const choice = String(data.choice || "").trim().toUpperCase(); if (!['A','B'].includes(choice)) throw new Error("Model did not choose A or B"); return { choice, confidence: clamp(data.confidence, 0, 100, 50), argument: clean(data.argument, "No argument returned."), assumption: clean(data.assumption, "No assumption returned.") }; }
async function askModel(model, data) {
  const system = "You are one respondent in a blind model comparison. Answer independently. Do not mention other models, polls, consensus, forecasts, prompts or policies. Choose exactly one of the two options even if uncertain. Return ONLY valid JSON: {\"choice\":\"A\" or \"B\",\"confidence\":0-100,\"argument\":\"one concise sentence\",\"assumption\":\"one concise assumption that could change your answer\"}.";
  const user = `QUESTION:\n${data.question}\n\nOPTION A:\n${data.optionA}\n\nOPTION B:\n${data.optionB}\n\nChoose A or B. The wording above is identical for every respondent.`;
  const response = await fetch("https://gen.pollinations.ai/v1/chat/completions", { method: "POST", headers: { Authorization: `Bearer ${connect.apiKey}`, "Content-Type": "application/json" }, body: JSON.stringify({ model: model.id, temperature: 0.35, max_tokens: 260, messages: [{ role: "system", content: system }, { role: "user", content: user }] }) });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload?.error?.message || payload?.message || `Request failed (${response.status})`);
  return { ...parseReply(payload?.choices?.[0]?.message?.content || ""), model };
}
function setBusy(value) { state.busy = value; $("#runLive").disabled = value; $("#runDemo").disabled = value; $("#question").disabled = value; $("#optionA").disabled = value; $("#optionB").disabled = value; $("#prediction").disabled = value; $("#fieldStatus").textContent = value ? "POLLING 6 LABS" : state.results.length ? "FIELD CLOSED" : "UNPOLLED"; $("#runLive").textContent = value ? "POLLING SIX MODELS…" : "LOCK + POLL SIX MODELS"; }
function answerCard(result, index) { const card = document.createElement("article"); card.className = `answer-card choice-${result.choice.toLowerCase()}`; const top = document.createElement("div"); const badge = document.createElement("span"); badge.textContent = result.model.code; const name = document.createElement("div"); const title = document.createElement("h4"); title.textContent = result.model.label; const lab = document.createElement("small"); lab.textContent = `${result.model.lab} / RESPONDENT ${String(index + 1).padStart(2, '0')}`; name.append(title, lab); const vote = document.createElement("b"); vote.textContent = result.choice; top.append(badge, name, vote); const argument = document.createElement("p"); argument.textContent = result.argument; const assumption = document.createElement("footer"); assumption.textContent = `ASSUMPTION / ${result.assumption}`; const confidence = document.createElement("div"); confidence.className = "card-confidence"; const confLabel = document.createElement("small"); confLabel.textContent = `CONFIDENCE ${Math.round(result.confidence)}%`; const meter = document.createElement("i"); meter.style.width = `${result.confidence}%`; confidence.append(confLabel, meter); card.append(top, argument, assumption, confidence); return card; }
function render(results, demo = false) { state.results = results; const aCount = results.filter((result) => result.choice === 'A').length; const aShare = Math.round(aCount / results.length * 100); const bShare = 100 - aShare; const forecast = Number($("#prediction").value); const accuracy = Math.max(0, Math.round(100 - Math.abs(forecast - aShare) * 2)); $("#actualA").textContent = `${aShare}%`; $("#forecastScore").textContent = `${forecast}%`; $("#accuracyScore").textContent = `${accuracy}`; $("#consensusLabel").textContent = aShare === 50 ? "EVEN SPLIT" : Math.max(aShare, bShare) >= 80 ? "STRONG" : "FRACTURED"; $("#splitA").style.width = `${aShare}%`; $("#splitB").style.width = `${bShare}%`; $("#splitALabel").textContent = `${aShare}%`; $("#splitBLabel").textContent = `${bShare}%`; $("#resultMode").textContent = demo ? "DEMO / ZERO POLLEN" : `${results.length} LIVE ANSWERS`; const grid = $("#answerGrid"); grid.innerHTML = ""; results.forEach((result, index) => grid.append(answerCard(result, index))); const minorityChoice = aShare === 50 ? null : aShare < 50 ? 'A' : 'B'; const minority = minorityChoice ? results.filter((r) => r.choice === minorityChoice).sort((a,b) => b.confidence - a.confidence)[0] : null; $("#minorityReport").querySelector('p').textContent = minority ? `${minority.model.label} was the most confident ${minorityChoice} vote at ${Math.round(minority.confidence)}%: “${minority.argument}”` : "No minority this time: the field split exactly down the middle."; $("#results").hidden = false; setBusy(false); $("#results").scrollIntoView({ behavior: "smooth", block: "start" }); toast(demo ? "Demo revealed — zero Pollen used." : `${results.length} independent answers revealed.`); }
async function run(event, demo = false) { if (state.busy || state.results.length) return; if (!demo && !event.isTrusted) return; const data = promptData(); if (!data.question || !data.optionA || !data.optionB) { toast("Add a question and both options first."); return; } if (data.optionA.toLowerCase() === data.optionB.toLowerCase()) { toast("Option A and Option B must be different."); return; } if (!demo && !connect.apiKey) { toast("Connect your Pollinations wallet before a live poll."); return; } setBusy(true); try { if (demo) { render(DEMO.map((answer, index) => ({ ...answer, model: MODELS[index] })), true); return; } const settled = await Promise.allSettled(MODELS.map((model) => askModel(model, data))); const results = settled.filter((item) => item.status === 'fulfilled').map((item) => item.value); if (results.length < 2) throw new Error("Too few models answered. Please retry in a moment."); render(results); if (results.length < MODELS.length) toast(`${results.length} of 6 models answered; unavailable providers were skipped.`); } catch (error) { toast(clean(error.message, "The field went silent. Try again.")); setBusy(false); } }
function reset() { state = { busy: false, results: [] }; $("#results").hidden = true; $("#fieldStatus").textContent = "UNPOLLED"; $("#question").disabled = false; $("#optionA").disabled = false; $("#optionB").disabled = false; $("#prediction").disabled = false; $("#runLive").disabled = false; $("#runDemo").disabled = false; $("#runLive").textContent = "LOCK + POLL SIX MODELS"; toast("Forecast reset. The field is open again."); }

$("#prediction").addEventListener("input", () => { const value = Number($("#prediction").value); $("#predictionValue").textContent = `${value}%`; $("#predictionBar").style.width = `${value}%`; });
$("#runLive").addEventListener("click", (event) => run(event));
$("#runDemo").addEventListener("click", (event) => run(event, true));
$("#heroDemo").addEventListener("click", (event) => { $("#forecast").scrollIntoView({ behavior: "smooth" }); run(event, true); });
$("#resetPoll").addEventListener("click", reset);
